/**
 * Builtin tool descriptor registry (tool_descriptors.rs:46–666).
 *
 * Static metadata used by the headless whitelist and execution-policy checks:
 * sensitive baseline, side-effect class, watchdog timeout, grants scope hint
 * and the headless/PTC whitelist flags.
 */
export type ToolSensitivity = 'Low' | 'Medium' | 'High';
export type SideEffectClass = 'Read' | 'WriteLocal' | 'WriteRemote' | 'Irreversible';
export type GrantsScopeHint = 'builtin' | 'shell';

export interface ToolDescriptor {
  name: string;
  sensitivity: ToolSensitivity;
  readOnly: boolean;
  sideEffectClass: SideEffectClass;
  timeoutSecs: number | null;
  grantsScopeHint: GrantsScopeHint;
  headlessAllowed: boolean;
  ptcAllowed: boolean;
}

