const DESCRIPTOR_INDEX = new Map(BUILTIN_DESCRIPTORS.map((descriptor) => [descriptor.name, descriptor]));

/** tool_descriptors.rs:689–692: exact bare-name lookup, no prefix stripping. */
export function lookupToolDescriptor(name: string): ToolDescriptor | undefined {
  return DESCRIPTOR_INDEX.get(name);
}

/** tool_descriptors.rs:697–702. */
export function isHeadlessReadonly(toolName: string): boolean {
  const stripped = toolName.startsWith('builtin-') ? toolName.slice('builtin-'.length) : toolName;
  return lookupToolDescriptor(stripped)?.headlessAllowed === true;
}

/** tool_descriptors.rs:721–725. */
export function isPtcAllowed(toolName: string): boolean {
  const stripped = toolName.startsWith('builtin-') ? toolName.slice('builtin-'.length) : toolName;
  return lookupToolDescriptor(stripped)?.ptcAllowed === true;
}

